#include "mac_cases.inc"
#include "hid_trace.h"
#include <thread>
extern "C" void tud_hid_report_failed_cb(uint8_t,uint8_t,const uint8_t*,uint16_t);
static std::vector<hid_trace::Event> trace(){std::vector<hid_trace::Event> out;uint32_t after=0;for(unsigned i=0;i<17;++i){auto b=hid_trace::read(after);for(unsigned j=0;j<b.count;++j)out.push_back(b.events[j]);if(!b.count||!b.more)break;after=b.events[b.count-1].sequence;}return out;}
int main(int argc,char**argv){if(argc!=2)return 2;if(argv[1][0]!='G')return historical_mac_main(argc,argv);try{
 mscMock::reset();mock::reset();setup();check(startupControlledReady&&route_u::bindOwner(),"controlled owner");lower::reset();led_mock::nowUs=0;auto r=req();std::string id=argv[1];
 if(id=="G01"){check(!hid_trace::enabled(),"off by default");runSource("CAPSLOCK\n");check(trace().empty()&&dwellOf()==6,"off no events or timing policy change");}
 else if(id=="G02"){hid_trace::enable();select("mac");runSource("CAPSLOCK\n");auto es=trace();unsigned caps=0,terminal=0;for(auto e:es){if(e.kind==hid_trace::Kind::Accepted&&(e.detail&1))++caps;if(e.kind==hid_trace::Kind::Terminal)++terminal;}check(caps==1&&terminal==1&&dwellOf()>=500,"real queue and owner path observed");}
 else if(id=="G03"||id=="G04"||id=="G05"){
  hid_trace::enable();select("mac");put("/x.txt",id=="G03"?"DELAY 5000\nCAPSLOCK\n":"CAPSLOCK\nDELAY 5000\nCAPSLOCK\n");start();if(id!="G03")trialPress();if(id=="G05")for(unsigned i=0;i<600;++i)trialTick();handleStop(&r);check(r.code==202,"STOP request accepted");trialDone();auto es=trace();uint32_t observed=0;unsigned capsAfter=0,term=0;for(auto e:es){if(e.kind==hid_trace::Kind::StopObserved)observed=e.sequence;if(observed&&e.kind==hid_trace::Kind::Accepted&&(e.detail&3))++capsAfter;if(e.kind==hid_trace::Kind::Terminal)++term;}check(observed&&capsAfter==0&&term==1&&!route_u::owned(),"only neutral cleanup after observed STOP");auto n=lower::count;for(int i=0;i<1000;++i)trialTick();check(lower::count==n,"no orphan reports at idle");}
 else if(id=="G06"){hid_trace::enable();runSource("CAPSLOCK\n");auto n=lower::count;handleStop(&r);for(int i=0;i<1000;++i)trialTick();check(lower::count==n&&!route_u::owned(),"STOP after complete emits no new key");}
 else if(id=="G07"){hid_trace::enable();runSource("CAPSLOCK\n");input(true);input(false);auto es=trace();unsigned n=0;for(auto e:es)if(e.kind==hid_trace::Kind::Completed){++n;check(e.run==0&&e.operation==0,"completion has no fabricated transfer correlation");}check(n==2,"actual completion slice traced");}
 else if(id=="G08"){tinyusb_hid_devices[0]={mockKeyboard,1,ids};hid_trace::enable();uint8_t mask=2;tud_hid_set_report_cb(0,1,2,&mask,1);auto es=trace();check(es.size()==2&&es[0].kind==hid_trace::Kind::RawOutput&&es[1].kind==hid_trace::Kind::LedAccepted&&es[1].detail==2&&es[1].run==0,"host output separate from firmware input");}
 else if(id=="G09"){hid_trace::enable();tud_hid_report_failed_cb(0,1,nullptr,0);auto es=trace();check(es.size()==1&&es[0].kind==hid_trace::Kind::TransferFailed&&lower::count==0,"SDK failure hook observes no retry");}
 else if(id=="G10"){hid_trace::enable();for(int i=0;i<1000;++i)hid_trace::note(hid_trace::Source::Usb,hid_trace::Kind::RawOutput);auto b=hid_trace::read(0);check(b.first==873&&b.latest==1000&&b.overwritten==872&&b.count==8&&b.more,"bounded ring with explicit evidence gap");check(trace().size()==128,"pagination bounded complete retained tail");}
 else if(id=="G11"){hid_trace::enable();led_mock::nowUs=hid_trace::WindowUs;hid_trace::note(hid_trace::Source::Owner,hid_trace::Kind::Phase);check(!hid_trace::enabled()&&trace().empty(),"finite capture auto expires on event/read");}
 else if(id=="G12"){r.headers.clear();handleHidTrace(&r,1);check(r.code==401&&!hid_trace::enabled(),"enable authenticated");handleHidTrace(&r,0);check(r.code==401,"read authenticated");}
 else if(id=="G13"){put("/x.txt","DELAY 5000\n");start();handleHidTrace(&r,1);check(r.code==409&&!hid_trace::enabled(),"enable reset blocked while owned");route_u::stop();trialDone();}
 else if(id=="G14"){for(const char* v:{"-1","4294967296","1x",""}){r.query["after"]={v};handleHidTrace(&r,0);check(r.code==400,"sequence bounds");}}
 else if(id=="G15"){hid_trace::enable();runSource("STRING private-not-retained\n");handleHidTrace(&r,0);check(r.code==200&&r.response.indexOf("private-not-retained")<0&&r.response.indexOf("callbackRunCorrelation\":false")>=0,"typed text not trace data");}
 else if(id=="G16"){hid_trace::enable();put("/x.txt","CAPSLOCK\n");start();trialPress();mock::usbMounted=false;tud_umount_cb();trialDone();auto n=lower::count;mock::usbMounted=true;tud_mount_cb();for(int i=0;i<100;++i)trialTick();check(lower::count==n&&route_u::status().reason!=route_u::Reason::Completed,"disconnect no replay");}
 else if(id=="G17"){hid_trace::enable();put("/x.txt","CAPSLOCK\n");start();for(int i=0;i<1000&&std::string(route_b::phase())!="Press";++i)trialTick();lower::next=lower::Outcome::FalseAfterPossibleAcceptance;trialTick();trialDone();auto b=hid_trace::read(0);check(b.counters[unsigned(hid_trace::Kind::Refused)]==1&&route_u::status().phase==route_u::Phase::Quarantined,"ambiguous outcome retained as error");}
 else if(id=="G18"){hid_trace::enable();runSource("CAPSLOCK\n");auto first=route_u::status().request;runSource("CAPSLOCK\n");auto second=route_u::status().request;auto es=trace();unsigned one=0,two=0;for(auto e:es)if(e.kind==hid_trace::Kind::Accepted&&(e.detail&1)){one+=e.run==first;two+=e.run==second;}check(first!=second&&one==1&&two==1,"back-to-back generation correlation");}
 else if(id=="G19"){hid_trace::enable();hid_trace::disable();runSource("CAPSLOCK\n");check(trace().empty()&&dwellOf()==6,"disable changes no output policy");}
 else if(id=="G20"){hid_trace::enable();for(unsigned i=0;i<30;++i)hid_trace::note(hid_trace::Source::Owner,hid_trace::Kind::Phase,65535,UINT64_MAX);handleHidTrace(&r,0);check(r.code==200&&r.response.length()<2304&&r.response.indexOf("\"more\":true")>=0,"bounded HTTP page");}
 else if(id=="G21"){hid_trace::enable();auto writer=[](){for(unsigned i=0;i<100;++i)hid_trace::note(hid_trace::Source::Usb,hid_trace::Kind::RawOutput);};std::thread a(writer),b(writer);a.join();b.join();auto snap=hid_trace::read(0);check(snap.latest==200&&snap.overwritten==72&&snap.counters[16]==200,"concurrent callbacks accounted with fixed capacity");auto es=trace();for(size_t i=1;i<es.size();++i)check(es[i].sequence==es[i-1].sequence+1,"coherent sequence under concurrent publication");}
 else if(id=="G22"){led_mock::nowUs=100;hid_trace::enable();led_mock::nowUs=99;hid_trace::note(hid_trace::Source::Usb,hid_trace::Kind::RawOutput);auto b=hid_trace::read(0);check(!b.enabled&&b.clockErrors==1&&b.latest==0,"backward clock disables capture without fabricated order");}
 else if(id=="G23"){hid_trace::enable();hid_trace::admit(77,500);hid_trace::httpReceipt(12,false);auto es=trace();check(es.size()==2&&es[1].run==12,"HTTP receipt retains its own request not current owner generation");}
 else if(id=="G24"){hid_trace::enable();hid_trace::admit(77,500);hid_trace::note(hid_trace::Source::Backend,hid_trace::Kind::Accepted,1,0);auto es=trace();check(es.size()==2&&es[1].run==0,"unleased backend output never attributed to prior owner");}
 else check(false,"unknown case");if(id=="G04"||id=="G06"||id=="G18"){for(auto e:trace())std::cout<<"TRACE "<<e.sequence<<" "<<e.atUs<<" "<<e.run<<" "<<e.operation<<" "<<hid_trace::name(e.source)<<" "<<hid_trace::name(e.kind)<<" "<<e.detail<<"\n";}
 std::cout<<"PASS "<<id<<" ("<<assertions<<" assertions)\n";return 0;
 }catch(const std::exception&e){std::cerr<<"FAIL "<<argv[1]<<": "<<e.what()<<" ("<<assertions<<")\n";return 1;}}
